yakit.AutoInitYakit() // 初始化Yakit环境

status = (i) => {
    yakit.StatusCard("状态", i) // 更新状态卡片
}

handle = func(origin /* string */) { 
    if str.ParseStringToPorts(origin).Len() <= 0 {
        status("输入不合法：%v" % origin)
        return ""
    }

    buf = bufio.NewBuffer() // 结果缓冲区
    filter = str.NewFilter() // 参数过滤器
    count = 0 // 处理计数器

    // 启动进度更新协程（注意：需处理协程终止问题）
    go func() {
        for {
            if count > 0 {
                yakit.StatusCard("进度", "已检查%v个参数" % count)
            }
            log.Debug("checking process")
            time.Sleep(1) // 修正为合理休眠时间
        }
    }()

    // 遍历输入的端口ID
    for port in str.ParseStringToPorts(origin) {
        // 先获取基础流量（可能用于获取Host信息）
        for result in db.QueryHTTPFlowsByID(port) {
            host = str.ExtractHost(result.Url) // 提取域名
            for protocol in ["https://" + host, "http://" + host] {
                // 根据协议和Host过滤流量
                for flow in yakit.QueryHTTPFlowsByKeyword(protocol) {
                    if !str.HasPrefix(flow.Url, protocol) {
                        continue
                    }

                    // 获取请求方法
                    method = flow.Method
                    if method != "GET" && method != "POST" {
                        continue // 只处理GET和POST请求
                    }

                    // 获取参数
                    params = make(map[string]var)
                    if method == "GET" {
                        // 解析GET参数
                        params = poc.GetAllHTTPPacketQueryParamsFull(flow.Request)
                    } else if method == "POST" {
                        // 解析POST参数
                        // 表单数据
                        params = poc.GetAllHTTPPacketPostParamsFull(flow.Request)
                    }

                    // 处理参数
                    for key in params {
                        if !filter.Exist(key) {
                            // yakit.Info(key)
                            count++
                            filter.Insert(key)
                            buf.Write(key + "\n") // 记录参数名
                        }
                    }
                }
            }
        }
    }

    return buf.String()
}
